template <class T> inline Array<double> atan(const Array<T>& a){ return apply1(a,[](double x){return std::atan(x);}); }
template <class T> inline Array<double> exp(const Array<T>& a){ return apply1(a,[](double x){return std::exp(x);}); }
template <class T> inline Array<double> log(const Array<T>& a){ return apply1(a,[](double x){return std::log(x);}); }
template <class T> inline Array<double> sqrt(const Array<T>& a){ return apply1(a,[](double x){return std::sqrt(x);}); }
template <class T> inline Array<double> fabs(const Array<T>& a){ return apply1(a,[](double x){return std::fabs(x);}); }
template <class T> inline Array<double> floor(const Array<T>& a){ return apply1(a,[](double x){return std::floor(x);}); }
